source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # The frame color occupies matching runs on a pair of opposite borders.
    candidates = []
    for color in counts:
        if color == bg:
            continue
        ht = sum(v == color for v in grid[0]) + sum(v == color for v in grid[-1])
        vt = sum(row[0] == color for row in grid) + sum(row[-1] == color for row in grid)
        if ht and vt:
            candidates.append((max(ht, vt), color, ht >= vt))
        elif ht:
            candidates.append((ht, color, True))
        elif vt:
            candidates.append((vt, color, False))
    _, frame, horizontal = max(candidates)
    ink = next(c for c in counts if c not in (bg, frame))

    def runs(vals):
        result = []
        i = 0
        while i < len(vals):
            if vals[i] != frame:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == frame:
                j += 1
            result.append((i, j))
            i = j
        return result

    if horizontal:
        top = runs(grid[0])
        bottom = runs(grid[-1])
        def lanes(run):
            a, b = run
            n = b - a
            if n == 2:
                offsets = (0, 1)
            elif n >= 3:
                offsets = range(1, n - 1, 2)
            else:
                offsets = (0,)
            return [a + k for k in offsets]
        for c in [x for r in top for x in lanes(r)]:
            marker = next((r for r in range(1, h - 1) if grid[r][c] == ink), None)
            end = marker if marker is not None else h - 1
            for r in range(1, end):
                if grid[r][c] == bg:
                    out[r][c] = ink
            if marker is not None:
                out[marker][c] = 4
        for c in [x for r in bottom for x in lanes(r)]:
            marker = next((r for r in range(h - 2, 0, -1) if grid[r][c] == ink), None)
            start = marker if marker is not None else 0
            for r in range(start + 1, h - 1):
                if grid[r][c] == bg:
                    out[r][c] = ink
            if marker is not None:
                out[marker][c] = 4
    else:
        left_runs = runs([row[0] for row in grid])
        right_runs = runs([row[-1] for row in grid])
        for r in range(h):
            for c in range(w):
                if grid[r][c] != ink:
                    continue
                side = 0 if grid[r][0] == frame else (w - 1 if grid[r][-1] == frame else None)
                if side is None:
                    continue
                rruns = left_runs if side == 0 else right_runs
                seg = next(((a, b) for a, b in rruns if a <= r < b), None)
                if seg is None:
                    continue
                a, b = seg
                idx = r - a
                others = right_runs if side == 0 else left_runs
                other = next(((x, y) for x, y in others if y - x == b - a), None)
                if other is None:
                    other = others[0] if others else None
                # Extend the marker's ray from its border to the marker.
                if side == 0:
                    for cc in range(1, c):
                        if grid[r][cc] == bg: out[r][cc] = ink
                else:
                    for cc in range(c + 1, w - 1):
                        if grid[r][cc] == bg: out[r][cc] = ink
                out[r][c] = 4
                # The paired run carries the ray onward across the full row.
                if other is not None:
                    pr = other[0] + idx
                    if 0 <= pr < h:
                        if grid[pr][0] == frame:
                            rng = range(1, w)
                        elif grid[pr][-1] == frame:
                            rng = range(0, w - 1)
                        else:
                            rng = range(w)
                        for cc in rng:
                            if grid[pr][cc] == bg: out[pr][cc] = ink
    return out
'''
